entries[168798] = { ["name"] = "Handbuch des Taschendiebes", ["text"] = "Wirken in 5 sek.\nErmöglicht es, Eure Fähigkeit 'Taschendiebstahl' auf gegnerische Spielercharaktere anzuwenden und ihnen bis zu 5 Artefaktfragmente zu stehlen. Dabei unterliegt die Fähigkeit aber einer Abklingzeit von 10 Sek. Funktioniert nur in Ashran." }
entries[168799] = { ["name"] = "Schrifttafel des Geisterwolfs", ["text"] = "Wirken in 5 sek.\nErhöht sogar im Kampf die Bewegungsgeschwindigkeit in Geisterwolfgestalt auf die von epischen Reittieren und macht Euch nach 5 Sek. in Geisterwolfgestalt unsichtbar. Funktioniert nur in Ashran." }
