entries[168801] = { ["name"] = "Handbuch des heldenhaften Sprungs", ["text"] = "Wirken in 5 sek.\nEure Fähigkeit 'Heldenhafter Sprung' verfügt jetzt über 2 zusätzliche Aufladungen. Hält 1 Stunde lang an. Funktioniert nur in Ashran." }
entries[168802] = { ["name"] = "Buchband des Gefängniswärters", ["text"] = "Wirken in 5 sek.\nLehrt Euch den Zauber 'Urteil des Gefängniswärters'. Hält 1 Stunde lang an. Kann nur in Ashran verwendet werden." }
entries[168803] = { ["name"] = "Kodex des Aufstiegs", ["text"] = "Wirken in 5 sek.\nLehrt Euch den Zauber 'Aufstieg'. Hält 1 Stunde lang an. Kann nur in Ashran verwendet werden." }
