entries[168835] = { ["name"] = "Hexenzwirnstoff", ["text"] = "Wirken in 1.5 sek. 1 tag Abklingzeit\nReagenzien:\nPrächtiges Fell (20), Gorgrondfliegenfalle (10)\nProduziert 8 (plus zusätzliche, je nach Schneiderfertigkeit).\n\nKann auch magisches Wasser und/oder magische Luft erzeugen.\n\nDie Abklingzeit wird täglich abgeschlossen.\nVerkäufer:\nChristopher Macdonald\nGegenstand:\nSchneiderei von Draenor\nKosten:\n100\nZone:\nMondsturz\n\nVerkäufer:\nSteven Cochrane\nGegenstand:\nSchneiderei von Draenor\nKosten:\n100\nZone:\nAshran\n\nHexenzwirnstoff\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Zu feinem Stoff gewebtes Fell, das als Grundlage für die meisten Schneidereiprodukte in Draenor dient.\"" }
entries[168836] = { ["name"] = "Hexenzwirngarn", ["text"] = "Wirken in 1.5 sek.\nOhne Beruf:\nReagenzien:\nPrächtiges Fell (30)\nVerkäufer:\nPetir Sternenmeer\nZone:\nKriegsspeer\nKosten:\n1\n\nHexenzwirngarn\n35\n\"Es ist möglich, die Kräfte von Hexenzwirn durch Stickerei umzuleiten.\"" }
entries[168837] = { ["name"] = "Hexenzwirnmantel", ["text"] = "Wirken in 2 sek.\nOhne Beruf:\nReagenzien:\nHexenzwirnstoff (100), Echteisenerz (10)\nOptionale Reagenzien:\n[] (#31) , Hexenzwirnessenz (#241)\nVerkäufer:\nPetir Sternenmeer\nZone:\nKriegsspeer\nKosten:\n1\n\nHexenzwirnmantel\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)Schulter Stoff\n3 Rüstung\n+3 Intelligenz\n+5 Ausdauer\nHaltbarkeit 100 / 100\n35" }
entries[168838] = { ["name"] = "Hexenzwirngugel", ["text"] = "Wirken in 2 sek.\nOhne Beruf:\nReagenzien:\nHexenzwirnstoff (100), Echteisenerz (5)\nOptionale Reagenzien:\n[] (#31) , Hexenzwirnessenz (#241)\nVerkäufer:\nPetir Sternenmeer\nZone:\nKriegsspeer\nKosten:\n1\n\nHexenzwirngugel\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)Kopf Stoff\n3 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nHaltbarkeit 100 / 100\n35" }
