entries[169605] = { ["name"] = "Dragoner", ["text"] = "Level 1\nErmöglicht das Fangen und Ausbilden spezieller Reittiere auf Draenor. Lässt Euch außerdem im Freien von Draenor von Eurem Reittier aus mit Objekten interagieren.\n\nLevel 2\nGegnerische Angriffe machen Euch nicht mehr benommen, während Ihr im Freien von Draenor auf einem Reittier unterwegs seid.\n\nLevel 3\nErhöht die Reitgeschwindigkeit in Draenor um 20%." }
